const SCHEMA = {
  type: 'object',
  properties: {
    questions: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          question: { type: 'string' },
          scenario: { type: 'string' },
          options: { type: 'array', items: { type: 'string' }, minItems: 4, maxItems: 4 },
          answer_index: { type: 'integer' },
          explanation: { type: 'string' },
          commonMisconception: { type: 'string' },
          taxonomy: { type: 'string' },
        },
        required: ['question', 'options', 'answer_index', 'explanation', 'taxonomy'],
      },
    },
  },
  required: ['questions'],
}

function prompt(t) {
  return `你是國小四年級國語科出題老師。為「${t.title}」(${t.pn}版)補 ${t.gap} 道選擇題。

## 必讀
1. 單課研究紀錄(含課文全文錄製RC-01) knowledge/1_課綱研究/國語/四下/${t.pn}/KL4_四下_${t.pn}_L${t.n}_${t.title}_單課研究紀錄.md
2. 考古題與討論 knowledge/1_課綱研究/國語/四下/${t.pn}/KL4_四下_${t.pn}_L${t.n}_${t.title}_考古題與討論.md

## 規則(嚴格)
1. 每題必須具體引用本課課文的情節/人物/意象/字詞——換成別課課文就答不出來或不合理。禁止套版通用情境題。
2. **禁止設計成「四選項中僅一個是正向詞、其餘皆負向」這種可憑字面情感色彩猜中答案的題目**(例如純成語辨義題)——選項須有實質語意差異,須讀過課文才能判斷。
3. **每個選項須語意獨立、不重疊**，不可有兩個選項描述同一個心理狀態或事實只是用詞略異(避免無法排除次佳選項的模糊題)。
4. 禁止照抄考古題題幹/選項/誘答結構。
5. 欄位：question/scenario(可空)/options(4個)/answer_index(0-3)/explanation(與正解一致)/commonMisconception/taxonomy。
6. 難度四年級、誘答合理且唯一正解、正解位置隨機、禁洩答、非格式崩壞。
7. 避免與既有題重複，已涵蓋題幹(僅供避重複參考)：
${t.covered.map(c => '- ' + c).join('\n')}

回傳結構化結果，共 ${t.gap} 題。`
}

const results = await parallel(tasks.map(t => () =>
  agent(prompt(t), { label: `gap4:${t.d}_L${t.n}`, phase: '補題', model: 'sonnet', schema: SCHEMA })
    .then(r => ({ d: t.d, n: t.n, title: t.title, questions: r?.questions || null }))
))

return results
